<?php
namespace Tests\Feature;
use Tests\TestCase;use Tests\CreatesLedgerCompany;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Services\{JournalService,YearEndService,ReportService,PeriodService,SalesService};use App\Models\{FiscalYear,TaxCode};
class YearEndAndReportsTest extends TestCase {use RefreshDatabase,CreatesLedgerCompany;
 public function test_year_end_close_moves_result_to_retained_earnings_and_pnl_ignores_closing_mechanics():void{[$c,$u,$a]=$this->company();$this->actingAs($u);$sale=app(JournalService::class)->createDraft($c->id,$u->id,'2026-12-15','sale',[['account_id'=>$a['1110']->id,'debit'=>'100','credit'=>'0'],['account_id'=>$a['4100']->id,'debit'=>'0','credit'=>'100']]);app(JournalService::class)->post($sale,$u->id);$expense=app(JournalService::class)->createDraft($c->id,$u->id,'2026-12-16','expense',[['account_id'=>$a['5100']->id,'debit'=>'30','credit'=>'0'],['account_id'=>$a['1110']->id,'debit'=>'0','credit'=>'30']]);app(JournalService::class)->post($expense,$u->id);$fy=FiscalYear::forCompany($c->id)->where('year',2026)->first();foreach($fy->periods as $p)app(PeriodService::class)->close($p,$u->id);$closing=app(YearEndService::class)->close($fy,$u->id);$this->assertNotNull($closing);$this->assertTrue($closing->exclude_from_profit_loss);$pnl=app(ReportService::class)->profitAndLoss($c->id,'2026-01-01','2026-12-31');$revenue=collect($pnl)->firstWhere('code','4100');$expenseRow=collect($pnl)->firstWhere('code','5100');$this->assertEqualsWithDelta(100,(float)$revenue['amount'],.001);$this->assertEqualsWithDelta(30,(float)$expenseRow['amount'],.001);$bs=app(ReportService::class)->balanceSheet($c->id,'2026-12-31');$retained=collect($bs)->firstWhere('code','3100');$this->assertEqualsWithDelta(70,(float)$retained['amount'],.001);}
 public function test_zero_activity_year_closes_without_fake_zero_journal():void{[$c,$u]=$this->company();$this->actingAs($u);$fy=FiscalYear::forCompany($c->id)->where('year',2026)->first();foreach($fy->periods as $p)app(PeriodService::class)->close($p,$u->id);$this->assertNull(app(YearEndService::class)->close($fy,$u->id));$this->assertSame('closed',$fy->fresh()->status);}
 public function test_tax_summary_nets_credit_notes():void{[$c,$u,$a]=$this->company();$this->actingAs($u);$tax=TaxCode::create(['company_id'=>$c->id,'code'=>'T10','name'=>'10%','rate'=>'10','type'=>'sales','sales_account_id'=>$a['2200']->id,'active'=>true]);$customer=$this->customer($c);$i=app(SalesService::class)->createDraft($c->id,$u->id,['contact_id'=>$customer->id,'invoice_date'=>'2026-08-01','currency_id'=>$c->base_currency_id,'exchange_rate'=>'1'],[['description'=>'Sale','quantity'=>'1','unit_price'=>'100','revenue_account_id'=>$a['4100']->id,'tax_code_id'=>$tax->id]]);$i=app(SalesService::class)->post($i,$u->id);$cr=app(SalesService::class)->createCredit($i,$u->id,['invoice_date'=>'2026-08-02','exchange_rate'=>'1'],[['description'=>'Credit','quantity'=>'1','unit_price'=>'40','revenue_account_id'=>$a['4100']->id,'tax_code_id'=>$tax->id]]);app(SalesService::class)->post($cr,$u->id);$s=app(ReportService::class)->taxSummary($c->id,'2026-08-01','2026-08-31');$this->assertSame('6.000',$s['sales_tax']);}
}
